public boolean isPowerOfThree(int n) {
    // If n is less than or equal to zero, it can't be a power of three
    if (n <= 0) {
        return false;
    }

    // Check if n is a multiple of 3
    while (n % 3 == 0) {
        n /= 3;
    }

    // If n is not a multiple of 3, it cannot be a power of three
    return n == 1;
}
```

